try (var pool = Executors.newFixedThreadPool(workers)) {
    List<Callable<Double>> jobs = IntStream.range(0, workers)
        .mapToObj(i -> (Callable<Double>) () -> computePart(i))   // identical workers
        .toList();
    List<Future<Double>> parts = pool.invokeAll(jobs);            // dispatch + join
    double total = 0;
    for (Future<Double> f : parts) total += f.get();              // combine
}

try (var master = Executors.newVirtualThreadPerTaskExecutor()) {   // join at close
    List<Future<Double>> parts = IntStream.range(0, n)
        .mapToObj(i -> master.submit(() -> computePart(i)))          // one vthread each
        .toList();
    double total = 0;
    for (var f : parts) total += f.get();                            // combine
}

